/* @autogenerated */
import {
  Component,
  computed,
  contentChild,
  contentChildren,
  DestroyRef,
  effect,
  ElementRef,
  inject,
  Injector,
  input,
  linkedSignal,
  model,
  OnDestroy,
  OnInit,
  output,
  signal,
  untracked,
  viewChild,
  viewChildren,
} from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import {
  ListViewColumnDirective,
  ListViewEmptyDirective,
  ListViewErrorDirective,
  ListViewFocusableDirective,
  ListViewRowTemplate,
  ListViewSort,
  ListViewTableTemplate,
} from './list-view.directives';
import { CommonModule } from '@angular/common';
import { BreakpointObserver, Breakpoints, LayoutModule } from '@angular/cdk/layout';
import { FocusKeyManager } from '@angular/cdk/a11y';
import { Directionality } from '@angular/cdk/bidi';
import { filter, fromEvent, map, merge, pairwise, Subscription, tap, throttleTime } from 'rxjs';
import { CdkVirtualScrollViewport, ScrollingModule } from '@angular/cdk/scrolling';
import { MatProgressBarModule } from '@angular/material/progress-bar';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';
import { MatMenuModule } from '@angular/material/menu';
import { MatTooltipModule } from '@angular/material/tooltip';
import { TranslocoPipe } from '@jsverse/transloco';
import { SelectionModel } from '@shared/data/selection-model';
import { MatCardModule } from '@angular/material/card';
import { computeAvatarSpec, AvatarSpec } from '../avatar-text.service';
import { DisplayProvider } from '@shared/data/display-provider';

/** `auto`: lista en móvil y tabla en el resto; los demás fuerzan esa vista en cualquier anchura. */
export type ListViewMode = 'auto' | 'table' | 'card' | 'list';

/** Columna mostrada en la tabla con su anchura calculada. */
export interface ListViewTableColumn {
  column: ListViewColumnDirective;
  key: string;
  width: number;
  /** Columna sin título al final (acciones): se queda a la vista flotando sobre las demás si hay scroll horizontal. */
  pinned: boolean;
}

/** Reserva si `--list-view-row-height` no se puede leer en px; debe coincidir con `--app-row-height`. */
const DEFAULT_ROW_HEIGHT = 52;
/** Margen (px) hasta el final del scroll a partir del que se pide la página siguiente. */
const SCROLL_THRESHOLD = 50;
/** Arrastre táctil (px) hacia arriba, ya al final, que cuenta como gesto para buscar elementos nuevos. */
const OVERSCROLL_DRAG = 40;
/** Como mucho un gesto de "buscar más" por este intervalo. */
const OVERSCROLL_THROTTLE_MS = 1000;
const CHECK_WIDTH = 52;
const ICON_WIDTH = 42;
/** Hueco reservado al final de cabecera y filas para el botón "Columnas" (40px + margen). */
const COLUMN_MENU_WIDTH = 48;
const SKELETON_ROWS = 20;
const COLUMNS_STORAGE_PREFIX = 'list-view-columns-';

@Component({
  templateUrl: 'list-view.component.html',
  styleUrls: [
    'list-view.component.scss',
    'list-view.table.component.scss',
    'list-view.grid.component.scss',
    'list-view.list.component.scss',
  ],
  selector: 'list-view',
  standalone: true,
  imports: [
    CommonModule,
    LayoutModule,
    ScrollingModule,
    MatButtonModule,
    MatCheckboxModule,
    MatIconModule,
    MatMenuModule,
    MatProgressBarModule,
    MatCardModule,
    MatTooltipModule,
    TranslocoPipe,
    ListViewFocusableDirective,
  ],
  host: {
    '[style.--list-view-row-height]': 'rowHeight() ? rowHeight() + "px" : null',
  },
})
export class ListViewComponent implements OnInit, OnDestroy {
  next = output<void>();
  activate = output<any>();
  /** Se emite al pulsar "Reintentar" en el estado de error. */
  retry = output<void>();
  mobile = signal<boolean>(false);
  rowIcons = signal<number>(1);
  data = input.required<any[] | undefined>();
  mode = input<ListViewMode>('auto');
  display = input<DisplayProvider<any>>();
  selectionMultiple = input<boolean>(false);
  searching = input<boolean>();
  selectionModel = input<SelectionModel<any> | undefined>();
  /** Error de la última carga: si tiene valor se muestra el estado de error en lugar de los datos. */
  error = input<unknown>();
  /** Nombre accesible de la tabla o lista. */
  label = input<string>();
  /** Clave (p. ej. la entidad) con la que se guardan en `localStorage` las columnas elegidas; sin ella no se guardan. */
  storageKey = input<string>();
  /** Altura de fila en px; si no se indica manda `--list-view-row-height`. */
  rowHeight = input<number>();
  /** Orden actual; su output `sortChange` se emite al pulsar una cabecera ordenable. */
  sort = model<ListViewSort | null>(null);

  view = computed(() => {
    const mode = this.mode();
    return mode === 'auto' ? (this.mobile() ? 'list' : 'table') : mode;
  });

  tableTemplate = contentChildren(ListViewTableTemplate);
  theTableScroll = viewChild<CdkVirtualScrollViewport>('tableScroll');
  private theTableScrollX = viewChild<ElementRef<HTMLElement>>('tableScrollX');
  table = computed(() => {
    const theColumns = this.tableTemplate();
    return theColumns.length > 0 ? theColumns[0] : new ListViewTableTemplate();
  });

  rowTemplate = contentChildren(ListViewRowTemplate);
  theListScroll = viewChild<CdkVirtualScrollViewport>('listScroll');

  row = computed(() => {
    const theRows = this.rowTemplate();
    return theRows.length > 0 ? theRows[0] : new ListViewRowTemplate();
  });

  emptyTemplate = contentChild(ListViewEmptyDirective);
  errorTemplate = contentChild(ListViewErrorDirective);

  readonly skeleton = Array.from({ length: SKELETON_ROWS }, (_, index) => index);
  readonly checkWidth = CHECK_WIDTH;
  readonly columnMenuWidth = COLUMN_MENU_WIDTH;
  readonly retryFn = () => this.retry.emit();

  /** Altura de fila usada por el virtual scroll. */
  itemHeight = computed(() => this.rowHeight() ?? this.cssRowHeight());

  /** Columnas con título que el usuario puede mostrar u ocultar, con su clave estable. */
  choosableColumns = computed(() => this.keyedColumns().filter(({ column }) => !!column.title()));

  /** Elección del usuario por clave de columna; se relee al cambiar `storageKey`. */
  private columnChoice = linkedSignal<Record<string, boolean>>(() => readColumnChoice(this.storageKey()));

  tableLayout = computed(() => {
    const icons = this.rowIcons();
    const checks = this.selectionMultiple() ? CHECK_WIDTH : 0;
    const shown = this.keyedColumns().filter(({ column, key }) => this.isShown(column, key));
    const base = shown.map(({ column }) => (column.title() ? column.width() : ICON_WIDTH * icons));
    const used = checks + base.reduce((total, width) => total + width, 0);
    // Con el botón "Columnas" se reserva su hueco: si no, las columnas que caben justas quedarían debajo de él
    const menuSpace = this.choosableColumns().length > 1 ? COLUMN_MENU_WIDTH : 0;
    const available = this.availableWidth() - menuSpace;
    // Si no caben, se mantiene su anchura y la tabla hace scroll horizontal
    const spare = Math.max(0, available - used);
    const titled = shown.filter(({ column }) => !!column.title());
    const factors = titled.reduce((total, { column }) => total + Math.max(0, column.factor()), 0);
    const columns: ListViewTableColumn[] = shown.map(({ column, key }, index) => {
      let share: number;
      if (!titled.length) {
        share = 1 / shown.length;
      } else if (!column.title()) {
        share = 0;
      } else {
        share = factors > 0 ? Math.max(0, column.factor()) / factors : 1 / titled.length;
      }
      const pinned = !column.title() && shown.slice(index).every((entry) => !entry.column.title());
      return { column, key, width: base[index] + Math.floor(spare * share), pinned };
    });
    // El ancho incluye el hueco del botón: si no, con overflow las filas acabarían antes que la cabecera
    return { columns, width: Math.max(used, available) + menuSpace };
  });

  allSelected = computed(() => {
    const rows = this.data() ?? [];
    const selection = this.selectionModel();
    return !!selection && rows.length > 0 && rows.every((row) => selection.isSelected(row));
  });

  someSelected = computed(() => {
    const selection = this.selectionModel();
    return !!selection && !this.allSelected() && (this.data() ?? []).some((row) => selection.isSelected(row));
  });

  private keyedColumns = computed(() =>
    this.table()
      .columns()
      .map((column, index) => ({ column, key: column.key() ?? `#${index}` })),
  );

  private readonly elRef = inject<ElementRef<HTMLElement>>(ElementRef);
  private readonly direction = inject(Directionality, { optional: true });
  private readonly focusables = viewChildren(ListViewFocusableDirective);
  private readonly keyManager = new FocusKeyManager(this.focusables, inject(Injector)).withVerticalOrientation();
  private cssRowHeight = signal<number>(DEFAULT_ROW_HEIGHT);
  private scrollSubs = new Subscription();
  /** Datos con los que el autorrelleno pidió más por última vez: si no han cambiado, no se vuelve a pedir. */
  private filledWith?: string;
  private availableWidth = signal<number>(0);
  private resizeObserver?: ResizeObserver;

  public constructor() {
    inject(BreakpointObserver)
      .observe([
        Breakpoints.XLarge, // >=1920
        Breakpoints.Large, // 1280–1919.98
        Breakpoints.Medium, // 960–1279.98
        Breakpoints.Small, // 600–959.98
        Breakpoints.XSmall, // <600
      ])
      .pipe(takeUntilDestroyed())
      .subscribe(({ breakpoints: bp }) => {
        this.mobile.set(!!bp[Breakpoints.XSmall]);
        this.rowIcons.set(bp[Breakpoints.XLarge] ? 6 : bp[Breakpoints.Large] ? 5 : bp[Breakpoints.Medium] ? 4 : 1);
      });
    inject(DestroyRef).onDestroy(() => this.keyManager.destroy());

    effect(() => {
      // En tarjetas también se navega con las flechas laterales
      this.keyManager.withHorizontalOrientation(this.view() === 'card' ? (this.direction?.value ?? 'ltr') : null);
    });
    effect(() => {
      // Al cambiar los datos o terminar una búsqueda se vuelve a comprobar si hay que pedir más
      this.data();
      this.searching();
      this.refreshView();
    });
    effect((onCleanup) => {
      const element = this.theTableScrollX()?.nativeElement;
      if (element) {
        onCleanup(this.trackScrollEnd(element));
      }
    });
  }

  ngOnInit(): void {
    const element = this.elRef.nativeElement;
    // La altura de fila la define --list-view-row-height; el virtual scroll necesita conocerla en px
    this.cssRowHeight.set(this.readRowHeight(element));
    this.updateAvailableWidth();
    this.resizeObserver = new ResizeObserver(() => {
      this.updateAvailableWidth();
      // También al volver a mostrarse (estaba fuera del DOM y medía 0) o al crecer la ventana
      this.fillViewport();
    });
    this.resizeObserver.observe(element);
  }

  ngOnDestroy(): void {
    this.scrollSubs.unsubscribe();
    this.resizeObserver?.disconnect();
  }

  /**
   * Activar una fila (clic o Enter) aplica la acción por defecto. Con selección múltiple no toca la selección:
   * esa la llevan los checkboxes, y el contenedor de acciones ya selecciona el elemento al ejecutar la acción.
   */
  selectAndActivate(row: any) {
    if (!this.selectionMultiple()) {
      this.selectionModel()?.select([row]);
    }
    this.activate.emit(row);
  }

  check(row: any) {
    this.selectionModel()?.toggle(row);
  }

  isSelected(row: any) {
    return !!this.selectionModel()?.isSelected(row);
  }

  toggleAll() {
    const selection = this.selectionModel();
    if (!selection) {
      return;
    }
    if (this.allSelected()) {
      selection.clearSelection();
    } else {
      selection.select(this.data() ?? []);
    }
  }

  /** Enter activa, espacio selecciona y las flechas mueven el foco entre filas. */
  onItemKeydown(event: KeyboardEvent, row: any, item: ListViewFocusableDirective) {
    // Las teclas en los controles de dentro de la fila (menú de acciones, checkbox) son suyas
    if (event.target !== event.currentTarget) {
      return;
    }
    if (event.key === 'Enter') {
      event.preventDefault();
      this.selectAndActivate(row);
    } else if (event.key === ' ') {
      event.preventDefault();
      if (this.selectionMultiple()) {
        this.check(row);
      } else {
        this.selectionModel()?.select([row]);
      }
    } else {
      this.keyManager.updateActiveItem(item);
      this.keyManager.onKeydown(event);
    }
  }

  isColumnShown(key: string): boolean {
    const entry = this.keyedColumns().find((column) => column.key === key);
    return !!entry && this.isShown(entry.column, key);
  }

  /** Impide ocultar la última columna con título visible. */
  isLastShown(key: string): boolean {
    const shown = this.choosableColumns().filter((entry) => this.isShown(entry.column, entry.key));
    return shown.length === 1 && shown[0].key === key;
  }

  toggleColumn(key: string) {
    if (this.isLastShown(key)) {
      return;
    }
    const choice = { ...this.columnChoice(), [key]: !this.isColumnShown(key) };
    this.columnChoice.set(choice);
    writeColumnChoice(this.storageKey(), choice);
  }

  toggleSort(key: string) {
    const current = this.sort();
    if (current?.key !== key) {
      this.sort.set({ key, direction: 'asc' });
    } else if (current.direction === 'asc') {
      this.sort.set({ key, direction: 'desc' });
    } else {
      this.sort.set(null);
    }
  }

  ariaSort(column: ListViewColumnDirective, key: string): string | null {
    if (!column.sortable()) {
      return null;
    }
    const current = this.sort();
    return current?.key !== key ? 'none' : current.direction === 'asc' ? 'ascending' : 'descending';
  }

  fallbackIcon(str: any): AvatarSpec | null {
    const displayer = this.display();
    return displayer ? computeAvatarSpec(displayer.display(str)) : null;
  }

  private isShown(column: ListViewColumnDirective, key: string): boolean {
    return !column.title() || (this.columnChoice()[key] ?? column.defaultVisible());
  }

  private readRowHeight(element: HTMLElement): number {
    const value = parseFloat(getComputedStyle(element).getPropertyValue('--list-view-row-height'));
    return Number.isFinite(value) && value > 0 ? value : DEFAULT_ROW_HEIGHT;
  }

  /**
   * En la tabla se mide la zona con scroll (sin el borde del recuadro): con el ancho del host sobrarían esos px
   * y siempre habría un mínimo de scroll horizontal. Se redondea hacia abajo para no desbordar por subpíxeles.
   */
  private updateAvailableWidth(): void {
    const scroll = untracked(this.theTableScrollX)?.nativeElement;
    const width = scroll ? scroll.clientWidth : this.elRef.nativeElement.getBoundingClientRect().width;
    this.availableWidth.set(Math.floor(width));
  }

  /**
   * Publica en `--list-view-scroll-end` lo que queda de scroll horizontal hasta el final: las columnas ancladas
   * se desplazan eso hacia la izquierda y siempre quedan junto al borde derecho. Se escribe directamente en el
   * estilo para no lanzar la detección de cambios en cada evento de scroll.
   */
  private trackScrollEnd(element: HTMLElement): () => void {
    const table = element.parentElement!;
    const update = () => {
      // Al aparecer la tabla, su anchura útil sustituye a la del host
      this.updateAvailableWidth();
      // Menos de 1px es redondeo, no overflow real
      const rest = element.scrollWidth - element.clientWidth - Math.abs(element.scrollLeft);
      const end = rest >= 1 ? rest : 0;
      table.style.setProperty('--list-view-scroll-end', `${end}px`);
      table.classList.toggle('overflow-end', end > 0);
    };
    update();
    element.addEventListener('scroll', update, { passive: true });
    const observer = new ResizeObserver(update);
    observer.observe(element);
    if (element.firstElementChild) {
      observer.observe(element.firstElementChild);
    }
    return () => {
      element.removeEventListener('scroll', update);
      observer.disconnect();
    };
  }

  private refreshView() {
    const scroll = this.theTableScroll() ?? this.theListScroll();
    if (scroll) {
      scroll.checkViewportSize();
      this.attachScroll(scroll);
    }
  }

  private attachScroll(scroller: CdkVirtualScrollViewport) {
    setTimeout(() => {
      this.fillViewport();
      this.scrollSubs.unsubscribe();
      const element = scroller.elementRef.nativeElement;
      const atBottom = () => scroller.measureScrollOffset('bottom') < SCROLL_THRESHOLD;
      // Al acercarse al final con el scroll se pide la página siguiente
      const scrolled = scroller.elementScrolled().pipe(
        map(() => scroller.measureScrollOffset('bottom')),
        pairwise(),
        filter(([y1, y2]) => y2 < y1 && y2 < SCROLL_THRESHOLD),
        throttleTime(200),
      );
      // Ya al final no hay scroll: la rueda o un arrastre hacia arriba piden más (o la última página otra vez)
      let touchStart = 0;
      const overscrolled = merge(
        fromEvent<WheelEvent>(element, 'wheel', { passive: true }).pipe(filter((event) => event.deltaY > 0)),
        fromEvent<TouchEvent>(element, 'touchstart', { passive: true }).pipe(
          tap((event) => (touchStart = event.touches[0]?.clientY ?? 0)),
          filter(() => false),
        ),
        fromEvent<TouchEvent>(element, 'touchmove', { passive: true }).pipe(
          filter((event) => touchStart - (event.touches[0]?.clientY ?? touchStart) > OVERSCROLL_DRAG),
        ),
      ).pipe(
        filter(() => atBottom() && !untracked(this.searching)),
        throttleTime(OVERSCROLL_THROTTLE_MS),
      );
      this.scrollSubs = merge(scrolled, overscrolled).subscribe(() => {
        if (scroller.measureViewportSize('vertical') > SCROLL_THRESHOLD) {
          this.next.emit();
        }
      });
    });
  }

  /**
   * Si las filas no llenan el área visible no hay scroll con el que pedir más: se pide la página siguiente.
   * Al llegar, cambian los datos y se vuelve a comprobar, hasta llenarla o agotar las páginas. Si la última
   * petición no trajo nada nuevo (fin de la lista) no se insiste: buscar más queda para el gesto del usuario.
   * Fuera del DOM el viewport mide 0 y no se pide nada.
   */
  private fillViewport() {
    const scroller = untracked(() => this.theTableScroll() ?? this.theListScroll());
    if (!scroller) {
      return;
    }
    // El virtual scroll guarda el tamaño medido: al reaparecer hay que volver a medir para pintar las filas
    scroller.checkViewportSize();
    const data = untracked(this.data) ?? [];
    const signature = `${data.length}:${JSON.stringify(data[0] ?? null)}`;
    const emits =
      !untracked(this.searching) &&
      signature !== this.filledWith &&
      scroller.measureViewportSize('vertical') > SCROLL_THRESHOLD &&
      scroller.measureScrollOffset('bottom') < SCROLL_THRESHOLD;
    if (emits) {
      this.filledWith = signature;
      this.next.emit();
    }
  }
}

function readColumnChoice(storageKey: string | undefined): Record<string, boolean> {
  if (!storageKey) {
    return {};
  }
  try {
    const stored = JSON.parse(localStorage.getItem(COLUMNS_STORAGE_PREFIX + storageKey) ?? '{}');
    return typeof stored === 'object' && stored !== null ? stored : {};
  } catch {
    return {};
  }
}

function writeColumnChoice(storageKey: string | undefined, choice: Record<string, boolean>): void {
  if (!storageKey) {
    return;
  }
  try {
    localStorage.setItem(COLUMNS_STORAGE_PREFIX + storageKey, JSON.stringify(choice));
  } catch {
    // Sin cuota o en modo privado: la elección sigue en memoria
  }
}
